use crate::{msbq03 as m,catalog,model::*,rules::*,unit_support::*};
use crate::jc029_tests::{pass_top,envelope};
fn setup()->Game{let mut g=game();g.players[0].society_zone.card=Some(g.make_card(m::ID,0));fund(&mut g,0,"JC096",4);g}
fn host(g:&mut Game,seat:usize)->String{let c=g.make_card("BQ091",seat);let id=c.id.clone();g.attachments.push(Attachment{card:c,host_id:g.regions[0].card.id.clone()});id}
fn grave(g:&mut Game,id:&str,seat:usize)->String{let c=g.make_card(id,seat);let id=c.id.clone();g.players[seat].graveyard.push(c);id}
fn action(g:&Game,key:&str,target:Option<String>)->Action{Action{card_id:Some(g.players[0].society_zone.card.as_ref().unwrap().id.clone()),ability_id:Some(key.into()),target_id:target,..Action::new("activate")}}
fn bad(base:&Game,g:&Game){assert!(Game::from_persisted(&serde_json::to_string(g).unwrap()).is_err());let mut r=envelope(base);r.game=g.clone();assert!(crate::room::RoomEnvelope::from_persisted(&serde_json::to_string(&r).unwrap()).is_err());}
#[test]
fn msbq03_printed_black_six_closed_colors_and_corpse_copy_exception(){let s=crate::society::definition(m::ID).unwrap();assert_eq!((s.card.color.as_str(),s.starting_hand,s.subtitle.as_str()),("黑",6,"斯卡拉跨国集团"));assert!(!s.card.supported);for c in &catalog::catalog().cards{assert_eq!(crate::society::validate_construction(s,&[catalog::DeckEntry{card_id:c.id.clone(),count:1}],&catalog::catalog().cards).is_ok(),matches!(c.color.as_str(),"黑"|"白"|"中立"));}assert_eq!(crate::deck::copy_limit_for_society(catalog::card("XQ46"),Some(m::ID)),None);assert_eq!(crate::deck::copy_limit_for_society(catalog::card("XQ46"),None),Some(3));assert_eq!(crate::deck::copy_limit_for_society(catalog::card("BQ091"),Some(m::ID)),Some(3));validate_definitions(definitions()).unwrap();}
#[test]
fn msbq03_paid_seal_selects_after_response_reads_actual_grave_and_influence(){let mut g=setup();let h=host(&mut g,0);let corpse=grave(&mut g,"XQ46",0);grave(&mut g,"JC001",0);grave(&mut g,"XQ46",1);let a=action(&g,m::SEAL,Some(h.clone()));act(&mut g,0,a);assert_eq!(g.resources(0),3);assert!(g.players[0].graveyard.iter().any(|c|c.id==corpse));let later=grave(&mut g,"XQ46",0);pass_top(&mut g);assert_eq!(g.pending.as_ref().unwrap().choice.options.len(),2);choose(&mut g,vec![later]);assert_eq!(g.msbq03_influence(g.in_play(&h).unwrap().1),1);assert_eq!(g.current_icons(g.in_play(&h).unwrap().1,0).influence,catalog::card("BQ091").permanent_icons.influence+1);restore(&mut g);}
#[test]
fn msbq03_empty_grave_can_activate_but_invalid_host_cannot_and_response_loss_not_refunded(){let mut g=setup();let h=host(&mut g,0);let other=host(&mut g,1);let a=action(&g,m::SEAL,Some(other));reject(&mut g,0,a);let mut a=action(&g,m::SEAL,Some(h.clone()));a.cost_selected=Some(vec![]);reject(&mut g,0,a);let a=action(&g,m::SEAL,Some(h));act(&mut g,0,a);pass_top(&mut g);assert!(g.pending.is_none());assert_eq!(g.resources(0),3);
 let mut g=setup();let h=host(&mut g,0);let c=grave(&mut g,"XQ46",0);let a=action(&g,m::SEAL,Some(h.clone()));act(&mut g,0,a);g.return_hand(&h);pass_top(&mut g);assert!(g.pending.is_none());assert!(g.players[0].graveyard.iter().any(|x|x.id==c));assert_eq!(g.resources(0),3);}
#[test]
fn msbq03_influence_per_actual_host_printed_character_and_current_controller(){let mut g=setup();let h=host(&mut g,0);let h2=host(&mut g,0);for (id,target) in [("XQ46",&h),("JC125",&h),("JC005",&h),("XQ46",&h2)]{let c=g.make_card(id,0);g.seal_card_on_valid_host(c,0,target);}assert_eq!(g.msbq03_influence(g.in_play(&h).unwrap().1),2);assert_eq!(g.msbq03_influence(g.in_play(&h2).unwrap().1),1);g.attachments.iter_mut().find(|a|a.card.id==h).unwrap().card.controller=1;assert_eq!(g.msbq03_influence(g.in_play(&h).unwrap().1),0);g.attachments.iter_mut().find(|a|a.card.id==h).unwrap().card.controller=0;g.players[0].society_zone.card=None;assert_eq!(g.msbq03_influence(g.in_play(&h).unwrap().1),0);g.players[0].society_zone.card=Some(g.make_card(m::ID,0));g.return_hand(&h);assert!(!g.sealed_cards.iter().any(|s|s.host_id==h));assert_eq!(g.msbq03_influence(g.in_play(&h2).unwrap().1),1);restore(&mut g);}
#[test]
fn msbq03_search_reveals_not_draw_once_consumed_and_no_match_finishes(){for matches in [true,false]{let mut g=setup();deck_cards(&mut g,0,if matches{&["BQ091","JC125"]}else{&["JC125","JC125"]});let a=action(&g,m::SEARCH,None);act(&mut g,0,a);assert!(g.players[0].society_zone.used_once_per_game.contains(m::SEARCH));pass_top(&mut g);if matches{assert_eq!(g.pending.as_ref().unwrap().choice.options.len(),1);let id=g.pending.as_ref().unwrap().choice.options[0].id.clone();choose(&mut g,vec![id]);assert!(g.players[0].hand.iter().any(|c|c.definition=="BQ091"));}else{assert!(g.pending.is_none());}g.players[0].society_zone.card.as_mut().unwrap().exhausted=false;let a=action(&g,m::SEARCH,None);reject(&mut g,0,a);restore(&mut g);}}
#[test]
fn msbq03_corrupt_frame_pending_and_duplicate_reject_game_and_room(){let mut g=setup();let h=host(&mut g,0);grave(&mut g,"XQ46",0);let a=action(&g,m::SEAL,Some(h));act(&mut g,0,a);for n in 0..4{let mut x=g.clone();let f=x.stack.last_mut().unwrap().frame.as_mut().unwrap();match n{0=>f.already_paid.clear(),1=>f.source.card.definition="MSJC07".into(),2=>f.targets[0].spec.predicate=None,_=>f.steps[0].op=Op::MSBQ03{search:true}}bad(&g,&x);}pass_top(&mut g);for n in 0..5{let mut x=g.clone();let p=x.pending.as_mut().unwrap();match n{0=>p.choice.min=Some(0),1=>p.seat=1,2=>p.choice.options[0].id="i999999".into(),3=>if let ChoiceResolution::Frame{choice,..}=&mut p.resolution{*choice=FrameChoice::MSBQ03{search:true}},_=>if let ChoiceResolution::Frame{frame,..}=&p.resolution{x.effects.push_back(Effect::Frame{frame:frame.clone()})}}bad(&g,&x);}let mut d=m::definition();d.abilities[0].costs[0]=Cost::Assets(2);assert!(m::validate_definition(m::ID,&d).is_err());}
#[test]
fn msbq03_natural_construct_industry_mill_seal_search_room_chain(){
 use crate::{deck,abi112_review_play_tests::Trace};
 let mut d=deck::preset("watchers").unwrap();d.id="closed-scarab".into();d.name="圣甲虫封闭自然测试".into();d.description="非官方预组，44尸体3黑资产3研究所".into();d.society_id=Some(m::ID.into());d.cards=vec![catalog::DeckEntry{card_id:"XQ46".into(),count:44},catalog::DeckEntry{card_id:"JC096".into(),count:3},catalog::DeckEntry{card_id:"BQ093".into(),count:3}];assert!(deck::validate(d.clone()).is_err());let mut societies=catalog::catalog().societies.clone();societies.iter_mut().find(|s|s.card.id==m::ID).unwrap().card.supported=true;let d=deck::validate_with_registry(d,&catalog::catalog().cards,&societies).unwrap();let mut other=d.clone();other.society_id=None;other.cards=vec![catalog::DeckEntry{card_id:"JC125".into(),count:50}];let other=deck::validate(other).unwrap();
 let mut selected=None;for seed in 1..257{let mut g=Game::new("scarab-natural".into(),"LOCAL".into(),"teams".into(),"P0".into(),"watchers".into(),seed).unwrap();for seat in 1..4{g.join(format!("P{seat}"),"watchers".into()).unwrap();}g.start_validated_decks(vec![d.clone(),other.clone(),other.clone(),other.clone()]).unwrap();g.drive().unwrap();if ["JC096","BQ093"].iter().all(|id|g.players[0].hand.iter().any(|c|c.definition==*id)){selected=Some((seed,g));break;}}
 let(seed,g)=selected.expect("bounded real seed with black asset and industry");let mut t=Trace::new_preserving_rng(g,"msbq03-natural-industry-seal-search".into(),900);let mut sealed=false;let mut searched=false;let mut complete=false;
 for _ in 0..1000{if let Some(p)=t.room.game.pending.clone(){if matches!(p.resolution,ChoiceResolution::Forecast{..}|ChoiceResolution::Frame{choice:FrameChoice::Forecast{..},..}){let ids=p.choice.options.iter().map(|o|o.id.clone()).collect();t.action(p.seat,Action{choice_id:Some(p.choice.id),top:Some(ids),bottom:Some(vec![]),..Action::new("choose")});continue;}let ids=if p.choice.kind=="trigger"&&p.choice.options.iter().any(|o|o.id=="accept"){vec!["accept".into()]}else{let mut ids=p.choice.options.iter().map(|o|o.id.clone()).collect::<Vec<_>>();ids.sort_by_key(|id|t.room.game.players[p.seat].hand.iter().find(|c|c.id==*id).is_some_and(|c|matches!(c.definition.as_str(),"JC096"|"BQ093")));ids.truncate(p.choice.min.unwrap_or(0));ids};t.choose(ids);continue;}
  if searched&&t.room.game.stack.is_empty(){complete=true;break;}let g=&t.room.game;let legal=g.legal_actions(0);let mut a=None;
  if g.players[0].assets.len()<3{a=legal.iter().find(|a|a.action.kind=="asset"&&g.players[0].hand.iter().any(|c|Some(&c.id)==a.action.card_id.as_ref()&&if g.players[0].assets.is_empty(){c.definition=="JC096"}else{c.definition=="XQ46"})).map(|a|a.action.clone());}
  if a.is_none()&&!g.attachments.iter().any(|a|a.card.controller==0&&a.card.definition=="BQ093"){a=legal.iter().find(|a|a.action.kind=="play"&&g.players[0].hand.iter().any(|c|c.definition=="BQ093"&&Some(&c.id)==a.action.card_id.as_ref())).map(|a|a.action.clone());}
  if a.is_none()&&!sealed&&g.players[0].graveyard.iter().any(|c|c.definition=="XQ46"){a=legal.iter().find(|a|a.action.ability_id.as_deref()==Some(m::SEAL)).map(|a|a.action.clone());if a.is_some(){sealed=true;}}
  if a.is_none()&&sealed&&!g.sealed_cards.is_empty()&&!searched{a=legal.iter().find(|a|a.action.ability_id.as_deref()==Some(m::SEARCH)).map(|a|a.action.clone());if a.is_some(){searched=true;}}
  if let Some(a)=a{t.action(0,a);}else{t.pass();}
 }
 assert!(sealed&&searched&&complete,"natural chain turn {}, sealed {}, searched {}",t.room.game.turn,sealed,searched);assert!(!t.room.game.sealed_cards.is_empty());assert!(t.room.game.players[0].hand.iter().any(|c|c.definition=="BQ093"));
 let mut v=t.value();for step in v["steps"].as_array_mut().unwrap(){let room=crate::room::RoomEnvelope::from_persisted(step["expected"]["state"].as_str().unwrap()).unwrap();let cmd=serde_json::from_value(step["command"].clone()).unwrap();let dup=room.transition(step["seat"].as_u64().unwrap()as usize,Some(cmd),0).unwrap();assert_eq!(dup.outcome,"rejected");assert!(!dup.changed&&dup.journal.is_empty());assert_eq!(dup.state,step["expected"]["state"]);step["duplicate"]=serde_json::to_value(dup).unwrap();}v["construction"]=serde_json::json!({"deck":d,"seed":seed,"admission":"private candidate registry only","noLayoutOrResourceMutation":true});
 if let Ok(path)=std::env::var("MSBQ03_NATIVE_OUT"){use sha2::{Digest,Sha256};let mut b=crate::jc066_tests::source_bindings();for(name,bytes)in[("rust-game/src/msbq03.rs",include_bytes!("msbq03.rs").as_slice()),("rust-game/src/msbq03_tests.rs",include_bytes!("msbq03_tests.rs").as_slice()),("rust-game/src/attachment.rs",include_bytes!("attachment.rs").as_slice()),("rust-game/src/society.rs",include_bytes!("society.rs").as_slice()),("rust-game/src/deck.rs",include_bytes!("deck.rs").as_slice())]{b["files"].as_object_mut().unwrap().insert(name.into(),serde_json::json!(format!("{:x}",Sha256::digest(bytes))));}std::fs::write(path,serde_json::to_vec_pretty(&serde_json::json!({"catalog":catalog::catalog(),"sourceBindings":b,"cases":[v]})).unwrap()).unwrap();}
}
